  Object.assign(ru,{chatgptSelectAccount:'Сначала выберите аккаунт',serviceSectionTitle:'Вход через сервис',serviceSectionIntro:'Сейчас доступен ChatGPT. Войдите в аккаунт и разрешите Hub использовать доступные модели вашего плана.',connection:'Подключение',modelColumn:'Модель'});
  Object.assign(en,{chatgptSelectAccount:'Select an account first',serviceSectionTitle:'Service sign-in',serviceSectionIntro:'ChatGPT is currently supported. Sign in and allow Hub to use the models available through your plan.',connection:'Connection',modelColumn:'Model'});
  function t(key, params={}) { const full=`provider.${key}`; try { const result=global.HubI18n?.t?.(full,params); if(result&&result!==full)return result; } catch (_) {} const locale=global.HubI18n?.locale||global.document?.documentElement?.dataset?.hubLocale; return String((locale==='en'?en:ru)[key]||key).replace(/\{(\w+)\}/g,(_,n)=>params[n]==null?`{${n}}`:String(params[n])); }
  function esc(value) { return String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch])); }
  function requestId() { return (global.crypto?.randomUUID?.()||`${Date.now().toString(16)}${Math.random().toString(16).slice(2)}`).replace(/-/g,'').padEnd(32,'0').slice(0,32); }
  function connected(root) { return root && root.isConnected !== false; }
  async function api(url, options={}) {
    let response;
    try { response=await global.fetch(url,{cache:'no-store',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}}); }
    catch (cause) { const error=Error(t('mutationError')); error.uncertain=true; throw error; }
    let body; try { body=await response.json(); } catch (_) {}
    if(!response.ok) { const error=Error(t('mutationError')); error.uncertain=response.status>=500; error.revisionConflict=body?.error==='provider_revision_conflict';error.code=body?.error; throw error; }
    if(!body||typeof body!=='object'||Array.isArray(body)) { const error=Error(t('invalidAck')); error.uncertain=true; throw error; }
    return body;
  }
  async function authApi(url, options={}) {
    try { return await api(url,options); }
    catch(error) { error.message=t({chatgpt_account_in_use:'chatgptAccountInUse',chatgpt_account_busy:'chatgptAccountBusy',chatgpt_account_sign_out_required:'chatgptSignOutRequired',chatgpt_provider_settings_invalid:'chatgptForgetError'}[error.code]||'chatgptError');throw error; }
  }

  function authStatus(account) { const key={connected:'chatgptConnected',signed_out:'chatgptSignedOut',reauth_required:'chatgptReauth',plan_disabled:'chatgptPlanDisabled',refresh_unknown:'chatgptRefreshUnknown',refresh_pending:'chatgptRefreshPending'}[account?.status]||'chatgptRefreshUnknown'; return t(key); }
  function attemptStatus(status) { return t({pending:'chatgptPending',completed:'chatgptConnected',failed:'chatgptFailed',cancelled:'chatgptCancelled',expired:'chatgptExpired'}[status]||'chatgptRefreshUnknown'); }
  function authAccount(id) { return (view.auth.accounts||[]).find(account=>account.id===id); }
  function preferredAuthAccount() {
    const accounts=view.auth.accounts||[];
    const selected=(view.data?.items||[]).find(item=>item.id===view.data?.default&&authProvider(item));
    return accounts.find(account=>account.id===selected?.authentication.accountId)||accounts.find(account=>account.status==='connected'&&account.planUsageEnabled)||accounts[0]||null;
  }
  function authModels(account) { return Array.isArray(account?.models)?account.models:[]; }
  function authProvider(item) { return item?.authentication?.method==='chatgpt_oauth'; }
  async function loadAuth(fresh=false) {
    if(view.auth.loadingPromise){await view.auth.loadingPromise;if(!fresh)return;}
    view.auth.loading=true;render();
    const pending=(async()=>{
      try { const body=await authApi('/api/chatgpt-auth');view.auth.accounts=Array.isArray(body.accounts)?body.accounts:[];if(view.auth.chooseSaved&&view.dialog==='chatgpt'){view.draft=authDraft(preferredAuthAccount());view.auth.chooseSaved=false;} }
      catch(error) { view.auth.error=error.message||t('chatgptError'); }
      finally { view.auth.loading=false;render(); }
    })();
    view.auth.loadingPromise=pending;
    await pending;
    if(view.auth.loadingPromise===pending)view.auth.loadingPromise=null;
  }

  function authDraft(account=null,item=null) { const id=account?.id||item?.authentication?.accountId||''; const selected=authAccount(id)||account; const models=authModels(selected); return {accountId:id,model:item?.model||models[0]?.slug||'',name:item?.name||'ChatGPT',networkMode:item?.networkMode==='system'?'system':'direct'}; }
  function modelsErrorText(code, diagnostic={}) { const key={chatgpt_models_invalid:diagnostic.category==='parse'?'chatgptModelsParse':'chatgptModelsInvalid',chatgpt_network_error:diagnostic.category==='response_limit'?'chatgptModelsResponseLimit':'chatgptModelsNetwork',chatgpt_sign_in_required:'chatgptModelsSignIn',chatgpt_plan_permission_required:'chatgptModelsPlan'}[code]||'chatgptModelsUnavailable'; return t(key); }
  function modelsDiagnosticMarkup(account) { const diagnostic=account?.modelsDiagnostic; if(!diagnostic||typeof diagnostic!=='object')return ''; const keys=['requestId','attempt','operation','scheme','host','port','networkMode','effectiveNetworkMode','durationMs','status','phase','category','httpStatus','upstreamRequestId','retryAfter','outcomeUnknown']; const safe=Object.fromEntries(keys.filter(key=>diagnostic[key]!==undefined).map(key=>[key,diagnostic[key]])); return Object.keys(safe).length?`<details class="provider-chatgpt-diagnostics"><summary>${esc(t('chatgptModelDetails'))}</summary><pre>${esc(JSON.stringify(safe,null,2))}</pre></details>`:''; }
  function providerRow(item, selected, disabled) { return `<tr data-provider-executor="${esc(item.id)}"><td><strong>${esc(item.name)}</strong><small>${esc(t(item.provider))}</small>${checkMarkup(item)}<small><code>${esc(item.endpoint||t('endpointDefaultSaved'))}</code></small></td><td><code>${esc(item.model)}</code><small>${esc(t(item.networkMode==='system'?'system':'direct'))}</small></td><td>${selected===item.id?`<span class="provider-selected">${esc(t('selected'))}</span>`:button(`data-provider-select="${esc(item.id)}"`,'select',disabled)}</td><td><div class="provider-actions">${button(`data-provider-probe="${esc(item.id)}"`,'probe',disabled)}${button(`data-provider-edit="${esc(item.id)}"`,'edit',disabled)}${button(`data-provider-delete="${esc(item.id)}"`,authProvider(item)?'deleteConnection':'remove',disabled)}</div></td></tr>`; }
  function providerTable(items, selected, disabled, emptyKey='empty') { const rows=items.map(item=>providerRow(item,selected,disabled)).join(''); return rows?`<div class="provider-table-scroll"><table aria-label="${esc(t('configuredTitle'))}"><thead><tr>${['connection','modelColumn','usage','actions'].map(key=>`<th scope="col">${esc(t(key))}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table></div>`:`<p>${esc(t(emptyKey))}</p>`; }
  Object.assign(ru,{chatgptConnectionTitle:'Подключение ChatGPT',chatgptConnectionHelp:'Для повторного входа выберите свой сохранённый аккаунт. Другой аккаунт или рабочее пространство добавляйте отдельно. Затем выберите модель и сохраните подключение.',chatgptAddConnection:'Добавить подключение ChatGPT',chatgptDifferentAccount:'Другой аккаунт или рабочее пространство',chatgptAddAccount:'Новый аккаунт ChatGPT',deleteConnection:'Удалить подключение',chatgptSavedAccounts:'Сохранённые аккаунты ChatGPT',chatgptAccountsHelp:'Удаление подключения убирает его настройки. Вход в ChatGPT хранится отдельно. «Выйти из аккаунта» завершает вход, а «Удалить аккаунт из Hub» убирает его из этого списка.',chatgptForget:'Удалить аккаунт из Hub',chatgptAccountInUse:'Чтобы удалить аккаунт из Hub, сначала удалите использующие его подключения.',chatgptForgetTitle:'Удалить аккаунт из Hub?',chatgptForgetHelp:'Hub выйдет из аккаунта «{name}» и удалит сохранённые данные входа. Аккаунт в OpenAI и история запросов Hub сохранятся.',chatgptForgetCancel:'Назад',chatgptForgetError:'Не удалось удалить аккаунт. Обновите состояние и повторите действие.',chatgptAccountBusy:'Сейчас выполняется вход. Завершите или отмените его перед удалением аккаунта.',chatgptSignOutRequired:'Сначала выйдите из аккаунта, затем удалите его из Hub.',chatgptLoadingAccounts:'Обновление состояния аккаунтов…',chatgptSignInForModels:'Войдите в аккаунт, чтобы выбрать модель',chatgptBrowserHelp:'Ожидается вход в браузере. Если страница не открылась, используйте ссылку «Открыть страницу авторизации». При ошибке доступа проверьте, открывается ли auth.openai.com в вашем браузере. Сетевой режим относится к запросам Hub.',chatgptSignedOut:'Вы вышли из аккаунта',chatgptAccountHelp:'Выберите аккаунт для этого подключения.',deleteOAuthHelp:'Будут удалены настройки подключения Hub «{name}». Аккаунт ChatGPT останется в списке сохранённых аккаунтов. Его можно удалить отдельно.',chatgptRefresh:'Обновить статус входа'});
  Object.assign(en,{chatgptConnectionTitle:'ChatGPT connection',chatgptConnectionHelp:'Choose your saved account to sign in again. Add another account or workspace only when needed. Then choose a model and save the connection.',chatgptAddConnection:'Add ChatGPT connection',chatgptDifferentAccount:'Another account or workspace',chatgptAddAccount:'New ChatGPT account',deleteConnection:'Delete connection',chatgptSavedAccounts:'Saved ChatGPT accounts',chatgptAccountsHelp:'Deleting a connection removes its settings. ChatGPT sign-in is stored separately. Sign out ends that session; Remove account from Hub removes it from this list.',chatgptForget:'Remove account from Hub',chatgptAccountInUse:'Delete connections using this account before removing it from Hub.',chatgptForgetTitle:'Remove account from Hub?',chatgptForgetHelp:'Hub will sign out of “{name}” and remove its saved sign-in data. Your OpenAI account and Hub request history will remain.',chatgptForgetCancel:'Back',chatgptForgetError:'The account could not be removed. Refresh its status and try again.',chatgptAccountBusy:'Sign-in is in progress. Complete or cancel it before removing the account.',chatgptSignOutRequired:'Sign out before removing the account from Hub.',chatgptLoadingAccounts:'Refreshing account status…',chatgptSignInForModels:'Sign in to choose a model',chatgptBrowserHelp:'Waiting for sign-in in your browser. If the page did not open, use Open authorization page. If access fails, check whether auth.openai.com opens in your browser. The network mode applies to Hub requests.',chatgptSignedOut:'Signed out',chatgptAccountHelp:'Choose the account for this connection.',deleteOAuthHelp:'Hub connection “{name}” will be removed. The ChatGPT account will remain in saved accounts and can be removed separately.',chatgptRefresh:'Refresh sign-in status'});
  Object.assign(ru,{chatgptConnectionHelp:'Подключение хранит выбранные аккаунт и модель. Состояние авторизации ниже показывает, может ли Hub использовать этот аккаунт сейчас.',chatgptAuthorizationState:'Состояние авторизации',chatgptSignedInHelp:'Вход подтверждён. Повторно входить не нужно: Hub автоматически обновляет действующую авторизацию.',chatgptPendingHelp:'Аккаунт сохранён, но вход ещё не подтверждён. Ответ авторизации получен и ожидает проверки. Нажмите «Проверить авторизацию», чтобы продолжить без нового входа.',chatgptReconnectHelp:'Аккаунт сохранён, но рабочая авторизация не подтверждена. Для восстановления используйте «Войти снова в ChatGPT».',chatgptSignedOutHelp:'Аккаунт сохранён, но вы вышли из него в Hub. Войдите снова, чтобы использовать его для запросов.',chatgptPlanHelp:'Вход подтверждён, но аккаунт не разрешил Hub использовать модели по плану ChatGPT.',chatgptSignInAgain:'Войти снова в ChatGPT',chatgptVerifyAuthorization:'Проверить авторизацию',chatgptVerificationModels:'Авторизация ещё не подтверждена',chatgptCryptoHelp:'Hub не смог загрузить компонент проверки подписи. Восстановите компоненты Hub, затем повторите проверку авторизации. Повторный вход не устраняет эту ошибку.'});
  Object.assign(en,{chatgptConnectionHelp:'The connection stores the selected account and model. Authorization status below shows whether Hub can use this account now.',chatgptAuthorizationState:'Authorization status',chatgptSignedInHelp:'Sign-in is verified. You do not need to sign in again: Hub automatically renews valid authorization.',chatgptPendingHelp:'The account is saved, but sign-in is not verified yet. The authorization response was received and needs verification. Choose Verify authorization to continue without signing in again.',chatgptReconnectHelp:'The account is saved, but working authorization is not confirmed. Use Sign in to ChatGPT again to restore it.',chatgptSignedOutHelp:'The account is saved, but you have signed out in Hub. Sign in again to use it for requests.',chatgptPlanHelp:'Sign-in is verified, but the account has not allowed Hub to use models through the ChatGPT plan.',chatgptSignInAgain:'Sign in to ChatGPT again',chatgptVerifyAuthorization:'Verify authorization',chatgptVerificationModels:'Authorization is not verified yet',chatgptCryptoHelp:'Hub could not load its signature verification component. Repair Hub components, then verify authorization again. Signing in again does not fix this error.'});
  function authStateHelp(account) {
    const key={connected:'chatgptSignedInHelp',refresh_pending:'chatgptPendingHelp',signed_out:'chatgptSignedOutHelp',plan_disabled:'chatgptPlanHelp'}[account.status]||'chatgptReconnectHelp';
    return t(key);
  }
  ru.chatgptAccountsHelp='Сохранённый аккаунт не означает, что вход сейчас подтверждён: смотрите состояние авторизации. Удаление подключения убирает его настройки. «Выйти из аккаунта» очищает авторизацию Hub, а «Удалить аккаунт ChatGPT» удаляет сохранённую запись.';
  en.chatgptAccountsHelp='A saved account does not mean sign-in is currently verified: check authorization status. ChatGPT sign-in is stored separately from connection settings. Sign out clears Hub authorization; Remove account from Hub removes the saved entry.';
  function authMarkup(disabled, savedItems=[], selected) {
    const accounts=view.auth.accounts||[];
    const account=authAccount(view.draft.accountId);
    const attempt=view.auth.attempt;
    const pending=attempt&&['pending'].includes(attempt.status);
    const busy=disabled||view.auth.loading;
    const fieldsDisabled=busy||pending;
    const accountOptions=`<option value="" ${view.draft.accountId?'':'selected'}>${esc(t(accounts.length?'chatgptDifferentAccount':'chatgptAddAccount'))}</option>`+accounts.map(item=>`<option value="${esc(item.id)}" ${item.id===view.draft.accountId?'selected':''}>${esc(item.label||item.email||'ChatGPT')}</option>`).join('');
    const models=account?.status==='connected'?authModels(account):[];
    const modelOptions=models.map(item=>`<option value="${esc(item.slug)}" ${item.slug===view.draft.model?'selected':''}>${esc(item.displayName||item.slug)}</option>`).join('');
    const accountMarkup=accounts.map(item=>{
      const used=(view.data?.items||[]).some(connection=>authProvider(connection)&&connection.authentication.accountId===item.id);
      const controls=`${item.status==='plan_disabled'?`<a href="https://chatgpt.com/#settings/Usage" target="_blank" rel="noopener noreferrer">${esc(t('chatgptPlanLink'))}</a>`:''}${item.status==='connected'?button(`data-chatgpt-models="${esc(item.id)}"`,'chatgptModels',fieldsDisabled):''}${item.status!=='signed_out'?button(`data-chatgpt-logout="${esc(item.id)}"`,'chatgptLogout',fieldsDisabled):''}${button(`data-chatgpt-forget="${esc(item.id)}"`,'chatgptForget',fieldsDisabled||used)}`;
      return `<div class="provider-chatgpt-account"><strong>${esc(item.label||item.email||'ChatGPT')}</strong><span>${esc(authStatus(item))}</span><div class="provider-actions">${controls}</div>${used?`<small>${esc(t('chatgptAccountInUse'))}</small>`:''}</div>`;
    }).join('');
    const canSave=account?.status==='connected'&&account.planUsageEnabled&&view.draft.model&&models.some(item=>item.slug===view.draft.model);
    const authorize=pending&&attempt.authorizePath?`<a href="${esc(attempt.authorizePath)}" target="_blank" rel="noopener noreferrer" data-chatgpt-authorize>${esc(t('chatgptAuthorize'))}</a>`:'';
    const authAction=pending?`${authorize}${button('data-chatgpt-refresh','chatgptRefresh',busy)}${button('data-chatgpt-cancel','chatgptCancel',busy)}`:account?.status==='refresh_pending'?button(`data-chatgpt-models="${esc(account.id)}"`,'chatgptVerifyAuthorization',busy):account?.status==='connected'&&account.planUsageEnabled?button('data-chatgpt-save','chatgptSave',busy||!canSave):button('data-chatgpt-start',account?'chatgptSignInAgain':'chatgptStart',busy);
    const warning=view.auth.warning?`<p role="alert">${esc(view.auth.warning)} <a href="https://chatgpt.com/#settings/Usage" target="_blank" rel="noopener noreferrer">${esc(t('chatgptPlanLink'))}</a></p>`:'';
    const accountDetails=accounts.length?`<details class="provider-chatgpt-accounts"><summary>${esc(t('chatgptSavedAccounts'))}</summary><p class="provider-help">${esc(t('chatgptAccountsHelp'))}</p>${accountMarkup}</details>`:'';
    const modal=view.dialog==='chatgpt'?`<dialog data-provider-dialog aria-labelledby="chatgpt-dialog-title">
      <h3 id="chatgpt-dialog-title">${esc(t('chatgptConnectionTitle'))}</h3><p>${esc(t('chatgptConnectionHelp'))}</p>${warning}
      ${view.auth.error?`<p role="alert">${esc(view.auth.error)}</p>`:''}${view.auth.loading?`<p role="status">${esc(t('chatgptLoadingAccounts'))}</p>`:''}
      <label>${esc(t('chatgptAccount'))}<select name="accountId" ${fieldsDisabled?'disabled':''}>${accountOptions}</select></label>
      ${account?`<p class="provider-help"><strong>${esc(t('chatgptAuthorizationState'))}: ${esc(authStatus(account))}</strong><br>${esc(authStateHelp(account))}</p>`:''}
      <label>${esc(t('chatgptModel'))}<select name="model" ${fieldsDisabled||!models.length?'disabled':''}>${modelOptions||`<option value="">${esc(t(!account?'chatgptSelectAccount':account.status==='connected'?'chatgptNoModels':account.status==='refresh_pending'?'chatgptVerificationModels':'chatgptSignInForModels'))}</option>`}</select></label>
      ${account?.modelsError?`<p role="alert">${esc(modelsErrorText(account.modelsError,account.modelsDiagnostic))}</p>${modelsDiagnosticMarkup(account)}`:''}
      <label>${esc(t('chatgptName'))}<input name="name" value="${esc(view.draft.name)}" ${fieldsDisabled?'disabled':''}></label>
      <label>${esc(t('chatgptNetwork'))}<select name="networkMode" ${fieldsDisabled?'disabled':''}><option value="direct" ${view.draft.networkMode!=='system'?'selected':''}>${esc(t('chatgptDirect'))}</option><option value="system" ${view.draft.networkMode==='system'?'selected':''}>${esc(t('chatgptSystem'))}</option></select></label>
      ${attempt?`<p role="status">${esc(attemptStatus(attempt.status))}</p>`:''}${pending?`<p class="provider-help">${esc(t('chatgptBrowserHelp'))}</p>`:''}
      ${accountDetails}<div class="provider-actions">${authAction}${pending?'':button('data-provider-close','cancel',busy)}</div></dialog>`:'';
    return `<section class="provider-chatgpt-section"><div class="section-head"><div><h3>${esc(t('serviceSectionTitle'))}</h3><p>${esc(t('serviceSectionIntro'))}</p></div>${button('data-chatgpt-new','chatgptAddConnection',disabled)}</div><p class="provider-help">${esc(t('chatgptNoToken'))}</p>${providerTable(savedItems,selected,disabled,'chatgptEmpty')}${modal}</section>`;
  }
  async function pollAuth(attempt=view.auth.attempt) { if(!attempt||attempt.status!=='pending'||view.auth.busy||view.auth.attempt!==attempt)return; view.auth.busy=true; try { const body=await authApi(`/api/chatgpt-auth?attemptId=${encodeURIComponent(attempt.attemptId)}`); Object.assign(attempt,body); if(attempt.status==='pending'&&view.auth.attempt===attempt&&connected(view.root))global.setTimeout?.(()=>{if(view.auth.attempt===attempt&&attempt.status==='pending'&&connected(view.root))void pollAuth(attempt);},1500); else if(attempt.status==='completed'){render(); await Promise.all([loadAuth(true),load()]); if(view.auth.attempt===attempt){const account=authAccount(attempt.accountId);view.draft.accountId=attempt.accountId||view.draft.accountId;const models=authModels(account);if(!view.draft.model||!models.some(item=>item.slug===view.draft.model))view.draft.model=models[0]?.slug||'';}} } catch(error) { view.auth.error=error.message||t('chatgptError'); } finally { view.auth.busy=false; render(); } }
  async function startAuth() {
    if(view.auth.busy||view.auth.loading)return;
    const payload={action:'start',requestId:requestId(),networkMode:view.draft.networkMode,...(view.draft.accountId?{accountId:view.draft.accountId}:{})};
    let popup=null;
    try { popup=global.open?.('about:blank','_blank')||null;if(popup)popup.opener=null; } catch(_) {}
    view.auth.busy=true;view.auth.error='';view.auth.warning='';render();
    try {
      const body=await authApi('/api/v1/chatgpt-auth',{method:'POST',body:JSON.stringify(payload)});
      const path=typeof body.attemptId==='string'?'/auth/chatgpt/authorize?attemptId='+encodeURIComponent(body.attemptId):null;
      if(body.status==='pending'&&(!path||body.authorizePath!==path))throw Error(t('chatgptError'));
      view.auth.attempt={...body,accountId:body.accountId||view.draft.accountId};
      if(body.status==='pending'){
        if(popup&&!popup.closed)popup.location.replace(path);
        view.auth.busy=false;void pollAuth();
      }else{popup?.close?.();view.auth.busy=false;}
    } catch(error) { popup?.close?.();view.auth.error=error.message||t('chatgptError');view.auth.busy=false; }
    finally { render(); }
  }

  async function refreshAuth() { if(!view.auth.attempt||view.auth.busy)return; view.auth.busy=false; await pollAuth(); }
  async function cancelAuth() { const attempt=view.auth.attempt; if(!attempt||view.auth.busy)return; view.auth.busy=true; try { view.auth.attempt=await authApi('/api/v1/chatgpt-auth',{method:'POST',body:JSON.stringify({action:'cancel',attemptId:attempt.attemptId,requestId:requestId()})}); } catch(error) { view.auth.error=error.message||t('chatgptError'); } finally { view.auth.busy=false; render(); } }
  async function refreshModels(accountId) { if(view.auth.busy)return; view.auth.busy=true; view.auth.error=''; try { await authApi('/api/v1/chatgpt-auth',{method:'POST',body:JSON.stringify({action:'models',accountId,requestId:requestId()})}); } catch(error) { view.auth.error=error.message||t('chatgptError'); } finally { await loadAuth(); const account=authAccount(accountId); const models=authModels(account); if(accountId===view.draft.accountId&&(!view.draft.model||!models.some(item=>item.slug===view.draft.model)))view.draft.model=models[0]?.slug||''; view.auth.busy=false; render(); } }
  async function logoutAccount(accountId) { if(view.auth.busy)return; view.auth.busy=true; try { const result=await authApi('/api/v1/chatgpt-auth',{method:'POST',body:JSON.stringify({action:'logout',accountId,requestId:requestId()})}); view.auth.warning=result?.revocationConfirmed===false?t('chatgptLogoutWarning'):''; view.auth.attempt=null;await Promise.all([loadAuth(true),load()]); } catch(error) { view.auth.error=error.message||t('chatgptError'); } finally { view.auth.busy=false; render(); } }
  async function forgetAccount() {
    const account=view.auth.forgetting;if(!account||view.auth.busy)return;
    view.auth.busy=true;view.auth.error='';render();
    try {
      let logout=null;
      if(account.status!=='signed_out')logout=await authApi('/api/v1/chatgpt-auth',{method:'POST',body:JSON.stringify({action:'logout',accountId:account.id,requestId:requestId()})});
      const removed=await authApi('/api/v1/chatgpt-auth',{method:'POST',body:JSON.stringify({action:'forget',accountId:account.id,requestId:requestId()})});if(removed.accountId!==account.id||removed.status!=='forgotten')throw Error(t('chatgptForgetError'));
      view.auth.attempt=null;view.auth.forgetting=null;view.dialog='chatgpt';
      if(view.draft.accountId===account.id)view.draft=authDraft();
      view.auth.warning=logout?.revocationConfirmed===false?t('chatgptLogoutWarning'):'';
    } catch(error) { view.auth.error=error.message||t('chatgptForgetError'); }
    finally { await Promise.all([loadAuth(true),load()]);view.auth.busy=false;render(); }
  }
  function submitChatGPT() { if(!view.data||view.auth.busy)return; const payload={action:'save-chatgpt',expected:view.data.revision,requestId:requestId(),name:view.draft.name,model:view.draft.model,accountId:view.draft.accountId,networkMode:view.draft.networkMode,...(view.editing?{id:view.editing}:{})}; return mutate(payload,'save-chatgpt'); }
  function controls(root=view.root) { return {form:root?.querySelector?.('[data-provider-form]'), name:root?.querySelector?.('[name="name"]'), provider:root?.querySelector?.('[name="provider"]'), model:root?.querySelector?.('[name="model"]'), endpoint:root?.querySelector?.('[name="endpoint"]'), apiKey:root?.querySelector?.('[name="apiKey"]'), networkMode:root?.querySelector?.('[name="networkMode"]')}; }
  function capture(root=view.root) { const c=controls(root); return {...view.draft,name:c.name?.value??view.draft.name,provider:c.provider?.value??view.draft.provider,model:c.model?.value??view.draft.model,endpoint:c.endpoint?.value??view.draft.endpoint,apiKey:c.apiKey?.value??view.draft.apiKey,networkMode:c.networkMode?.value??view.draft.networkMode}; }
  function options() { return [['responses','responses'],['anthropic','anthropic'],['gemini','gemini'],['chat','chat']].map(([id,key])=>`<option value="${id}" ${view.draft.provider===id?'selected':''}>${esc(t(key))}</option>`).join(''); }
  function field(name, label, help, input) { return `<div class="provider-field"><label for="provider-${name}">${esc(label)}</label><p class="provider-help" id="provider-${name}-help">${esc(help)}</p>${input}</div>`; }
  function button(attr,label,disabled=false) { return `<button type="button" ${attr} ${disabled?'disabled':''}>${esc(t(label))}</button>`; }
  const transportKeys=['requestId','attempt','operation','oauthAction','identityReason','scheme','host','port','networkMode','effectiveNetworkMode','durationMs','timeoutMs','tlsReason','tlsVerifyCode','parseReason','responseMediaType','responseContentEncoding','responseBodyKind','responseBytes','status','phase','category','httpStatus','providerErrorCode','providerErrorType','upstreamRequestId','retryAfter','outcomeUnknown'];
  function checkMarkup(item) {
    const check=item.availability||{status:'not_checked'};
    const label=Object.prototype.hasOwnProperty.call(en,`check_${check.status}`)?t(`check_${check.status}`):t('check_not_checked');
    const date=Number.isFinite(check.checkedAt)?new Date(check.checkedAt*1000).toLocaleString(global.HubI18n?.locale==='en'?'en-US':'ru-RU'):'';
    return `<small>${esc(authProvider(item)?t('authOAuth'):t('authAPI'))}${authProvider(item)&&item.authentication?.label?` · ${esc(item.authentication.label)}`:''}</small><small data-provider-check>${esc(label)}${date?` · ${esc(date)}`:''}</small>`;
  }
  ru.probeTimeoutBeforeResponse='Время ожидания истекло до получения HTTP-ответа. По этим сведениям нельзя определить, задержалось ли соединение или обработка запроса сервисом.';
  en.probeTimeoutBeforeResponse='The request timed out before an HTTP response was received. These details cannot distinguish a connection delay from processing by the service.';
